style.css:
@-moz-document domain("scp-wiki.wikidot.com"), domain("scpwiki.com"), domain("scp-wiki.net"), domain("scp-wiki.wdfiles.com") {
/* BASE */

  /* Headings/links state colour on the element, so a light author box must rebind these tokens for its subtree. */
  :root {
    color-scheme: dark;
    --scp-title: #e05f6b;
    --scp-heading: #e6edf3;
    --scp-link: #e8626e;
    --scp-link-visited: #cf90a8;
    --scp-link-hover: #ff8f97;
    --scp-lift-black: #c4cdd6;
    --scp-lift-blue: #79c0ff;
    --scp-lift-green: #7ee787;
    --scp-lift-purple: #d2a8ff;
    --scp-lift-maroon: #ff9492;
    --scp-lift-red: #ff453a;
    --scp-lift-brown: #d4a373;
    --scp-lift-teal: #56d4dd;
    --scp-lift-pink: #ff7eb0;
  }

  /* BH's :root palette feeds the site chrome; the #page-content remap never reaches it. Only pure surface / body-ink tokens belong here: --swatch-background and --white-monochrome stay light, BH also using them as knocked-out text on crimson fills. */
  :root {
    --swatch-text-general: 196, 205, 214;
    --swatch-text-tertiary-color: 196, 205, 214;
    --swatch-menutxt-general-color: 196, 205, 214;
    --swatch-menubg-color: 20, 24, 29;
    --swatch-secondary-color: 34, 40, 47;
    --swatch-border-color: 45, 51, 59;
    --rating-module-bg-color: 26, 31, 38;
    --pager-text: 196, 205, 214;

    /* BH-derived themes name these on :root, bypassing the remap above. Page-options button row; Sigma-9 never reads them. */
    --ui-button-bg: 34, 40, 47;
    --ui-button-txt: 196, 205, 214;

    /* Also the fill behind both halves of the sidebar drawer scrim (#main-content::before, .close-menu, each at 30%); themes that swap the monochromes resolve it near-white. */
    --swatch-menubg-black-color: 5, 7, 10;

    /* Middle stop of --gradient-topmenu-mobile and --gradient-topmenu, read nowhere else, so this darkens the top band alone. */
    --swatch-topmenu-bg-color: 28, 33, 40;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  div#container-wrap,
  div#container-wrap-wrap,
  #container,
  #main-content,
  #page-content,
  #skrollr-body,
  #html-body {
    background-color: transparent;
  }

  /* Skins hang page artwork on #container-wrap and draw it under the article; some of it is light. These columns carry the page floor so the ink keeps its own ground. Below the masthead only: on Sigma-9 that art IS the masthead. */
  #content-wrap {
    background-color: #14181d !important;
  }

  /* Paper only. Do NOT restate the image: Sigma-9's body_bg.svg then paints onto BH pages, where the article theme's background-size and -repeat leave it a stray block. */
  div#container-wrap {
    background-color: #14181d !important;
  }

  /* iframes default to a 2px inset border in currentColor, which turns light when the page text does. */
  iframe {
    border-color: #2d333b;
  }

  /* TYPOGRAPHY */

  #page-title,
  h1,
  .meta-title {
    color: var(--scp-title) !important;
  }

  /* The pin stops at the title element: an h1 framed in an accent inside the article body is page identity, not chrome. */
  #page-title,
  .meta-title {
    border-color: #2d333b !important;
  }

  /* No border-color on purpose: guide-page section headings rule off with a colourless border, so currentColor carries the ink above; a chrome grey collapses it. */
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: var(--scp-heading);
  }

  /* Article root ONLY, so the ink inherits. A copy on p/li/dd/dt/td is a direct declaration that beats an author's callout-box colour, erasing their ink while leaving their light paper. */
  #page-content,
  .thread-container .post .content,
  .forum-thread-box .description-block {
    color: #c4cdd6;
  }

  /* BH paints article surfaces from this token layer; remapping tokens rather than components covers every widget they feed, hover-only ones included. Article body only - header, sidebar and top menu have their own rules. */
  #page-content {
    --swatch-background: 26, 31, 38;
    --swatch-text-general: 196, 205, 214;
    --swatch-border-color: 45, 51, 59;
    --tables-body-bg: 26, 31, 38;
    --tables-body-txt: 196, 205, 214;
    --tables-border: 45, 51, 59;
    --tables-header-bg: 34, 40, 47;
    --tables-header-txt: 230, 237, 243;
  }

  /* Callout boxes are authored as [[div style="background:#f2f2c2"]] with no ink, so the box hands the ink back. Matched on the VALUE (inline background plus a light hex or `white`), never on a class - classes are page-local. NOT !important, so an author's own ink still wins.
     A dark box with a pale border hex matches harmlessly: it must name its own light ink for the site's white page, and that beats this. Filtering needs a `color:`-bearing :not(), which also drops light boxes that DO name their ink and still need the rebinds below.
     `.content-panel` is excluded - ARTICLE FURNITURE fills it dark with !important, as must be any component filled that way - and returns when its inline background is an IMAGE, which paints over our fill. `##` is a malformed hex that paints nothing.
     Curated-series grids are the same shape one step out: their white plate is page CSS, so only cards naming an inline background COLOUR are excluded. */
  #page-content [style*="background"][style*="#c"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#d"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#e"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#f"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#C"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#D"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#E"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="#F"]:not(.content-panel):not([style*="##"]),
  #page-content [style*="background"][style*="white"]:not(.content-panel):not([style*="##"]),
  #page-content .content-panel[style*="url("],
  #page-content .multi-grid > div:not([style*="background:"]):not([style*="background-color"]),
  #page-content .multi-grid-small > div:not([style*="background:"]):not([style*="background-color"]) {
    color: #1b1815;
    --scp-title: #7a1d24;
    --scp-heading: #1b1815;
    --scp-link: #a4161a;
    --scp-link-visited: #6d3550;
    --scp-link-hover: #d21414;
    /* On paper BH's own light values are the right ones, so the remap is handed back for the box's contents. */
    --swatch-background: 252, 252, 252;
    --swatch-text-general: 27, 24, 21;
    --swatch-border-color: 160, 160, 160;
    --tables-body-bg: 252, 252, 252;
    --tables-body-txt: 27, 24, 21;
    --tables-border: 160, 160, 160;
    /* Same for the ##blue|...## palette: on paper the author's dark end reads and the lifted end does not. */
    --scp-lift-black: #1b1815;
    --scp-lift-blue: #0000cd;
    --scp-lift-green: #046307;
    --scp-lift-purple: #800080;
    --scp-lift-maroon: #800000;
    --scp-lift-red: #c30000;
    --scp-lift-brown: #6b4423;
    --scp-lift-teal: #006a6a;
    --scp-lift-pink: #a1004a;
  }

  /* A heading in a box stating its own `color:` follows that ink, not the paper value above. The match must be property-adjacent: a bare `color:` substring also sits inside `background-color:` and `--link-color:`, which hub cards carry without naming an ink. Wikidot echoes the author's spacing verbatim, so the forms matched are `color:` at the start of the attribute and `; color:` after a semicolon (`;color:` free); `-color:` longhands never match. */
  #page-content [style*="background"][style^="color:"] h1,
  #page-content [style*="background"][style*=";color:"] h1,
  #page-content [style*="background"][style*="; color:"] h1,
  #page-content [style*="background"][style^="color:"] h2,
  #page-content [style*="background"][style*=";color:"] h2,
  #page-content [style*="background"][style*="; color:"] h2,
  #page-content [style*="background"][style^="color:"] h3,
  #page-content [style*="background"][style*=";color:"] h3,
  #page-content [style*="background"][style*="; color:"] h3,
  #page-content [style*="background"][style^="color:"] h4,
  #page-content [style*="background"][style*=";color:"] h4,
  #page-content [style*="background"][style*="; color:"] h4,
  #page-content [style*="background"][style^="color:"] h5,
  #page-content [style*="background"][style*=";color:"] h5,
  #page-content [style*="background"][style*="; color:"] h5,
  #page-content [style*="background"][style^="color:"] h6,
  #page-content [style*="background"][style*=";color:"] h6,
  #page-content [style*="background"][style*="; color:"] h6 {
    color: inherit !important;
  }

  hr {
    color: #2d333b !important;
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }

  /* LINKS - the crimson identity, lifted for dark */

  a,
  #interwiki a,
  #side-bar a,
  #page-content a {
    color: var(--scp-link);
  }

  a:visited,
  #page-content a:visited {
    color: var(--scp-link-visited);
  }

  a:hover,
  #page-content a:hover {
    color: var(--scp-link-hover);
  }

  /* Article themes reach body links from page-scoped rules out-specifying one id. Two ids win on id count alone, so no !important is needed and inline colours and the ##name|text## lifts still take precedence. Every other article-link rule is doubled to this weight. */
  #main-content #page-content a {
    color: var(--scp-link);
  }

  #main-content #page-content a:visited {
    color: var(--scp-link-visited);
  }

  #main-content #page-content a:hover {
    color: var(--scp-link-hover);
  }

  /* Wikidot paints a light hover fill on every link. Low specificity so component rules (the rating buttons) can still fill their own hover. */
  a:hover {
    background-color: transparent !important;
  }

  a.newpage,
  a.newpage:visited,
  #main-content #page-content a.newpage,
  #main-content #page-content a.newpage:visited {
    color: #e8944a;
  }

  #page-content a.collapsible-block-link {
    color: var(--scp-link);
  }

  /* Article themes draw a light pill behind this shared rail's links, which the crimson ink cannot sit on. */
  #page-content .info-container a {
    background-color: transparent !important;
  }

  /* The front page colour-codes links by content type through --link-color; hand it back after the broad rule. */
  #main-content #page-content a.core-link,
  #page-content .masthead .line.middle {
    color: var(--link-color);
  }

  /* HEADER / TOP BAR */

  /* No colour on #header h1 a: Sigma-9 already paints it #eee, BH holds its span transparent, and the Sigma-derived skins hide the anchor's own text with `color: transparent` under a ::before copy - an ink here prints the title twice. */

  /* This span stays unstyled: BH hides it with `color: transparent` and draws its own ::before copy, so a colour here un-hides a second tagline. The tokens below are what that copy reads. */
  #header {
    --swatch-headerh1-color: 238, 238, 238;
    --swatch-headerh2-color: 240, 240, 192;
  }

  /* BH declares this on #top-bar itself, from the tertiary ink token remapped above at half alpha, and draws it as an inset ring on every dropdown item plus the two loose edges completing the phone menu's grid around its empty last cell. The item plates below cover the rings; the loose edges show, so it is pitched as a panel hairline. Two ids: the skin's own #top-bar declaration must lose on weight, not order. */
  #header #top-bar {
    --dropdown-border-color: 58, 64, 72;
  }

  /* For the themes that name the pseudo's colour outright, at #000. Sigma-9 gives these pseudos no content, so the rule costs nothing there. `color` only: -webkit-text-fill-color is what a background-clip title sets transparent so its artwork shows through. */
  #header h1 a::before,
  #header h1 a::after {
    color: #eee !important;
  }

  #header h2::before,
  #header h2::after,
  #header h2 span::before,
  #header h2 span::after {
    color: #f0f0c0 !important;
  }

  /* BH-derived themes repaint the masthead from their own palette, so this chrome states its ink rather than relying on cascade order. */
  #login-status {
    background-color: transparent !important;
    color: #9aa4ae !important;
  }

  #login-status a {
    color: #dde3e9 !important;
  }

  /* "Sign in" carries .btn-primary but renders as bare text on the masthead. */
  #login-status a.btn,
  #login-status a.btn-primary {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #dde3e9 !important;
  }

  /* The fill swap the rule above removes was BH's only hover cue here, so the ink carries one. */
  #login-status a.btn:hover,
  #login-status a.btn-primary:hover {
    color: #ff8f97 !important;
  }

  #login-status ul a,
  #account-options li a {
    color: #e8626e !important;
  }

  #account-options {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  #account-options li a:hover {
    color: #ff8f97 !important;
    background-color: #262c33 !important;
  }

  #account-topbutton {
    background-color: #2d333b !important;
    color: #e8626e !important;
    border-color: #3a4048 !important;
  }

  /* Bedrock and its derivatives put these labels on a white band, so the fill below gives every menu anchor its own dark plate; no other skin fills this anchor. theme:ch-scp-theme and theme:crocker-theme hold `color` at a near-black no !important dislodges - -webkit-text-fill-color paints the glyphs and must be restated on every rule below that states a colour. */
  #top-bar a {
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  /* The panel's own fill on BH: the anchor fills below cover the rows, not the gaps. Its elevation shadow comes from an ink token the remap turns pale, and the panel's own rule out-specifies this one, hence the !important. */
  #top-bar ul li ul {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    box-shadow: 0 4px 12px rgba(0, 0, 0, .7) !important;
  }

  #top-bar ul li a {
    background-color: #1c2128 !important;
    border-color: rgba(255, 255, 255, .06);
  }
  /* Open dropdown: the site paints these #eee / #fff */
  #top-bar ul li.sfhover a,
  #top-bar ul li:hover a,
  #top-bar li ul li a,
  #top-bar a:hover {
    background-color: #1c2128 !important;
    color: #ff8f97 !important;
    -webkit-text-fill-color: #ff8f97 !important;
    border-left-color: #3a4048 !important;
    border-right-color: #3a4048 !important;
  }

  #top-bar ul li.sfhover a:hover,
  #top-bar ul li:hover a:hover {
    background-color: #262c33 !important;
  }

  #top-bar ul li.sfhover ul li a,
  #top-bar ul li:hover ul li a {
    border-top-color: #2d333b !important;
  }

  #top-bar ul li ul a {
    color: #ff8f97;
  }

  /* This warning hangs off #top-bar, so the menu ink above reaches its links while the panel keeps its pink paper. The plate is cleared so the menu-hover rule drops no dark chip behind a link mid-paragraph. */
  #top-bar .ios-cache-issue-notification a {
    background-color: transparent !important;
    color: #a4161a !important;
    -webkit-text-fill-color: #a4161a !important;
  }

  #top-bar .ios-cache-issue-notification a:hover {
    background-color: transparent !important;
    color: #d21414 !important;
    -webkit-text-fill-color: #d21414 !important;
  }

  /* Mobile hamburger. BH-derived themes hold the glyph's `color` at a near-black no !important dislodges; -webkit-text-fill-color is what actually paints it. */
  #top-bar .open-menu a {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }

  #top-bar .open-menu a:hover {
    box-shadow: 0 0 16px 2px rgba(0, 0, 0, .8);
  }

  /* Below the desktop breakpoint the article themes fill their own bar with the background-IMAGE --gradient-topmenu-mobile, whose middle stop is the token remapped on :root. Do NOT state a flat fill instead: Sigma-9 leaves this element transparent and sized to the menu text, so a colour slabs over the masthead art at 390px. */
  #top-bar .mobile-top-bar {
    border-color: #3a4048 !important;
  }

  /* Outweighs the dropdown-item rule above, so the fill is restated or the two properties disagree here. Stops at the menu list: the hamburger is an .open-menu anchor with its own pair, which a bare `.mobile-top-bar a` would outweigh. */
  #top-bar .mobile-top-bar ul a {
    color: #eaeaea !important;
    -webkit-text-fill-color: #eaeaea !important;
  }

  /* Search button. BH clips this input to a mask-image and paints the magnifier with the element's own BACKGROUND, so a flat fill here becomes the icon's colour; the skins want opposite values, so it reads a token. The HOVER token on purpose - themes pitch the resting end near-black for their light bar.
     Skins keeping a real "Search" button take the dark fallback their near-white label needs. No background-IMAGE is stated, so Sigma-9's gradient survives. theme:newspaper, monotypical and cosmonaut draw the magnifier from #search-top-box::before in their accent and define no BH token, so the fallback is what that glyph reads against - hence the page floor, with the maroon kept on the border. */
  #search-top-box-form input[type="submit"] {
    background-color: #a05a5a !important;
    border-color: #6d4a4a !important;
  }

  /* The base fill above is !important and would freeze the skin's own hover swap. The fallback goes DARKER: the pressed cue is the border, and an accent glyph over this plate loses contrast against any lift. */
  #search-top-box-form input[type="submit"]:hover,
  #search-top-box-form input[type="submit"]:focus {
    background-color: #c07878 !important;
    border-color: #b98a8a !important;
  }


  /* No "Search" label colour in this build (the .user.css lights it from the same token as the plate). Without the token branch a single literal is wrong somewhere: light punches text-shaped flecks through the magnifier mask on every BH skin, plate-coloured blanks the label on the real-button skins (classic, decom-dept, derby, black-diamond, aces-and-eights). Those skins' own dark label stays and reads on the mid plate above. */

  /* BH masks this pseudo to a person icon below the desktop breakpoint and paints it from --login-mobile-icon-color, pitched near-black by the themes. No opposite case here - Sigma-9 gives the pseudo no content - so a flat fill, not a token branch. */

  /* BH masks this pseudo to a person icon below the desktop breakpoint and paints it from --login-mobile-icon-color, pitched near-black by the themes. No opposite case here - Sigma-9 gives the pseudo no content - so a flat fill, not a token branch. */
  #login-status::before {
    background-color: #c4cdd6 !important;
  }

  #search-top-box-input,
  #search-top-box input.text {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #3a4048 !important;
  }

  #search-top-box input.empty {
    color: #8b949e !important;
  }

  /* SIDE BAR */

  /* Articles with their own theme paint #side-bar directly, out of reach of the token rebind. Sigma-9 leaves it unpainted; several of those themes draw the border in currentColor. */
  #side-bar {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }

  #side-bar .side-block,
  #interwiki .side-block {
    background-color: #1c2128 !important;
    border-color: #7d3030 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .55);
  }

  /* The site tints two panels — keep those hues, at dark-surface lightness */
  #side-bar .side-block.media {
    background-color: #1e2133 !important;
  }

  #side-bar .side-block.resources {
    background-color: #17251d !important;
  }

  /* BH puts the block heading's colour on a <p> INSIDE .heading, which overrides what the rule below leaves it by inheritance, so its token is rebound too. */
  #side-bar,
  #interwiki {
    --sideblock-heading-text-color: 224, 123, 131;
    --sidebar-links-text: 196, 205, 214;
  }

  /* Several skins band this heading with a translucent light veil that inverts over the dark block; clearing it lands the label on the block's own plate. */
  #side-bar .heading,
  #interwiki .heading {
    background-color: transparent !important;
    color: #e07b83 !important;
    border-bottom-color: #7d3030 !important;
  }

  #side-bar .menu-item.inactive a {
    color: #7d858e !important;
  }

  #side-bar .menu-item .sub-text {
    color: #8b949e !important;
  }

  #side-bar .collapsible-block-unfolded-link {
    border-bottom-color: #7d3030 !important;
  }

  #side-bar .collapsible-block-unfolded-link .collapsible-block-link {
    color: #e07b83 !important;
  }

  #side-bar .collapsible-block-unfolded-link .collapsible-block-link:hover {
    color: #ff8f97 !important;
  }

  /* Mobile slide-out drawer */
  #side-bar .close-menu {
    background-color: rgba(0, 0, 0, .6);
  }

  /* Below 768px the drawer itself gets a dusty-rose fill from the site. */
  @media (max-width: 767px) {
    #side-bar {
      background-color: #0d1117 !important;
    }
  }

  /* TABLES */

  /* No ink here: td would beat an author box's inherited colour. Cell text inherits; th states its own. */
  table.wiki-content-table td,
  table.wiki-content-table th {
    border-color: #2d333b !important;
  }

  /* The id qualifier outranks a skin reaching these cells through #content-wrap: !important on a plain class chain loses to any id-scoped rule. */
  #main-content table.wiki-content-table th {
    background-color: #22282f !important;
    color: #e6edf3 !important;
  }

  /* A skin stating the cell fill outright beats the token remap. The second rule hands the cell back inside an author-painted box, where their paper survives and the ink rebind is pitched for it. */
  #main-content table.wiki-content-table td {
    background-color: #1a1f26 !important;
  }

  #page-content [style*="background"] table.wiki-content-table td {
    background-color: transparent !important;
  }

  table.page-compare td,
  table.page-compare th,
  table.form.grid td,
  table.form.grid th,
  .gallery-item,
  table.page-history td.optionstd a {
    border-color: #2d333b !important;
  }

  .alternate:nth-child(2n) {
    background-color: rgba(255, 255, 255, .04) !important;
  }

  table.page-files .highlight {
    background-color: #22282f !important;
  }

  /* CODE / TOC / NOTES / QUOTES */

  .code,
  #toc,
  .page-source,
  div.note {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Skins that give the table of contents its own paper plate this list too, landing a near-white panel inside the dark frame. Cleared so it takes the box's fill. */
  #toc-list {
    background-color: transparent !important;
  }

  div.note-block {
    border-color: #7d3030 !important;
    background-color: #1a1f26 !important;
  }

  /* This plate is ours and dark wherever it sits, so these tokens are restated: inside an author's light box the paper rule hands the subtree dark inks, which a heading or link here would print on this fill. */
  blockquote,
  div.blockquote {
    background-color: #1a1f26 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6;
    --scp-title: #e05f6b;
    --scp-heading: #e6edf3;
    --scp-link: #e8626e;
    --scp-link-visited: #cf90a8;
    --scp-link-hover: #ff8f97;
    --scp-lift-black: #c4cdd6;
    --scp-lift-blue: #79c0ff;
    --scp-lift-green: #7ee787;
    --scp-lift-purple: #d2a8ff;
    --scp-lift-maroon: #ff9492;
    --scp-lift-red: #ff453a;
    --scp-lift-brown: #d4a373;
    --scp-lift-teal: #56d4dd;
    --scp-lift-pink: #ff7eb0;
  }

  .hl-default,
  .hl-code,
  .hl-brackets,
  .hl-identifier,
  .hl-main {
    color: #c9d1d9 !important;
  }

  .hl-comment {
    color: #8b949e !important;
  }

  .hl-quotes,
  .hl-string {
    color: #a5d6ff !important;
  }

  .hl-reserved {
    color: #ff7b72 !important;
  }

  .hl-var {
    color: #79c0ff !important;
  }

  /* The two darkest tokens Wikidot's highlighter emits. A skin that restates them only moves them a shade, so both ends of the range need lifting. */
  .hl-number {
    color: #ffa657 !important;
  }

  .hl-special {
    color: #7ee787 !important;
  }

  .hl-inlinetags {
    color: #d2a8ff !important;
  }

  .hl-gutter {
    background-color: #22282f !important;
    color: #8b949e !important;
  }

  /* BH and its derivatives name this footer's fill directly rather than through the token, so it is stated here. */
  .footnotes-footer,
  .bibitems,
  .footnote-footer,
  .footnote .f-content,
  .reference .r-content {
    border-color: #2d333b !important;
    color: #c4cdd6;
  }

  #page-content .footnotes-footer {
    background-color: #1a1f26 !important;
  }

  /* The tab needs its own plate as well as its ink: article themes repaint it in accents from dark red to bright yellow, and no single ink reads on both. */
  #page-content .footnotes-footer .title {
    background-color: #22282f !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* BH draws a SECOND copy of the digit from a ::before counter and hides its own anchor, which the article-link rule above beats. Emptying the counter leaves one digit on either skin; hiding the anchor instead loses it on Sigma-9, which has no ::before. */
  #main-content #page-content .footnotes-footer a[href*="javascript"]::before {
    content: none !important;
  }

  /* White-on-transparent and only `visibility: hidden` until hovered; it is the article ink that has to read inside it. */
  #page-content .fncon {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  div.wiki-note,
  .hovertip {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
    box-shadow: 0 4px 14px rgba(0, 0, 0, .6);
  }

  /* Wikidot hangs these cards off the body, out of reach of every #page-content link rule. The id outweighs an article theme's class chain; an author's inline colour still wins. */
  #odialog-hovertips a {
    color: var(--scp-link);
  }

  #odialog-hovertips a:hover {
    color: var(--scp-link-hover);
  }

  .keycap {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  /* ARTICLE FURNITURE */

  /* No fill on purpose: the skins that give this frame a near-white one are giving the picture its paper - article images are routinely transparent PNGs in black linework. */
  .scp-image-block {
    border-color: #3a4048 !important;
    box-shadow: 0 1px 6px rgba(0, 0, 0, .5);
  }

  /* Article themes frame all four sides in their paper colour. Every side is stated - the three Sigma-9 leaves at zero width cost nothing. */
  .scp-image-block .scp-image-caption {
    background-color: #1c2128 !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  /* Article themes frame this panel in a near-white hairline, which is its whole outline on a dark page. */
  #page-content .info-container .collapsible-block-unfolded {
    border-color: #2d333b !important;
  }

  /* Drawn from whichever end of the article theme's paper/ink pair suits its light page, so it lands white on some and invisible on others; an elevated grey keeps it a separator everywhere. */
  #page-content .anom-bar .diamond-part::before {
    background-color: #2d333b !important;
  }

  /* The ACS component stretches an anchor over the graphic with `color: transparent` so only the artwork shows - one class, which the two-id article-link rule outweighs, printing the label in crimson with a stray underline (the border takes currentColor). */
  #main-content #page-content .danger-diamond a,
  #main-content #page-content .danger-diamond a:visited,
  #main-content #page-content .danger-diamond a:hover {
    color: transparent !important;
    border-color: transparent !important;
  }

  /* Same shape on the Wanderers' Library dustjacket: a first anchor stretched over the plate with `color: transparent`, the gold title drawn by the divs under it. */
  #main-content #page-content .library > a:first-of-type,
  #main-content #page-content .library > a:first-of-type:visited,
  #main-content #page-content .library > a:first-of-type:hover {
    color: transparent !important;
    border-color: transparent !important;
  }

  div.sexy-box {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  div.sexy-box div.image-container img {
    border-color: #3a4048 !important;
  }

  .content-panel {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .5);
  }

  .content-panel.standalone {
    background-color: #1a1f26 !important;
  }

  .content-panel .panel-body {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #c4cdd6;
  }

  .content-panel .panel-heading {
    color: #f0f0f0;
  }

  .content-panel .panel-footer {
    color: #d8d4c8;
  }

  .content-panel .content-toc {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    box-shadow: inset 1px 2px 6px rgba(0, 0, 0, .4);
  }

  /* /about-the-scp-foundation's letter is a marble background-IMAGE from page CSS, opaque and near-white, so the panel fill above never shows and the article ink lands on paper. Paper ink, as for an inline light box. */
  #page-content .content-panel.admin-letter {
    color: #1b1815;
  }

  div#u-adult-warning {
    background-color: #1c2128 !important;
    border-color: #4a5058 !important;
    color: #c4cdd6 !important;
  }

  div#u-adult-warning > div#u-adult-header {
    color: #e05f6b !important;
  }

  /* Drawn in the site's near-black crimson, which the bare `a` rule cannot outweigh. */
  div#u-adult-warning .choice a {
    color: #e8626e !important;
  }

  div#u-adult-warning .choice a:hover {
    color: #ff8f97 !important;
  }

  .unflad-user-abusive,
  .unflag-user-abusive {
    color: #e08a8a !important;
    border-color: #4a5058 !important;
  }

  .flag-user-abusive,
  .unflag-user-ok {
    color: #9aa4ae !important;
    border-color: #3a4048 !important;
  }

  .flag-user-ok {
    color: #3fb950 !important;
    border-color: #3a4048 !important;
  }

  /* Wikidot tag pill */
  .tags {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .tags::before {
    border-right-color: #3a4048 !important;
  }

  .tags::after {
    background-color: #c4cdd6 !important;
    box-shadow: -1px -1px 2px #14181d !important;
  }

  /* Sigma-9 draws this rule on the inner span; article themes move it to the container and keep their light hex there. */
  #main-content .page-tags {
    border-top-color: #2d333b !important;
  }

  /* Sigma-9's own copy of that rule, at 1px. Themes that moved it to the container leave this span an 8px TRANSPARENT spacer, which a colour alone fills as a slab, so the width is clamped. A width cannot revive a `border-top-style: none`. */
  #main-content .page-tags span {
    border-top-color: #2d333b !important;
    border-top-width: 1px !important;
  }

  /* Furniture, not author prose, so the ink is pinned against article themes that darken it. The paper comes with it: a theme filling each tag with a mid-grey chip states a knocked-out near-white ink for it, and the pinned ink alone sits on that grey at 2.9:1. */
  #main-content .page-tags span a,
  #page-content .footer-wikiwalk-nav a {
    background-color: transparent !important;
    color: #e8626e !important;
  }

  /* That chip's left point is a CSS triangle in the same fill, so it goes with it or a stray grey arrow is left in front of every tag. */
  #main-content .page-tags span a::before {
    border-color: transparent !important;
  }

  #main-content .page-tags span a:hover,
  #page-content .footer-wikiwalk-nav a:hover {
    color: #ff8f97 !important;
  }

  /* Wikidot writes the frequency gradient as inline per-tag colours, the whole range below AA on dark. Font size encodes the same frequency, so the signal survives. */
  .pages-tag-cloud-box a.tag {
    color: #e8626e !important;
  }

  .pages-tag-cloud-box a.tag:hover {
    color: #ff8f97 !important;
  }

  .pages-tag-cloud-box a.tag.active {
    color: #ffb3b8 !important;
  }

  /* The guide family's rail (/system:join, /guide-for-newcomers, /faq share one [[module CSS]]) tints itself rgba(191, 191, 191, .28), a mid grey over a dark page that drops the crimson links on it to 2.6:1. Two ids would be wrong: the page's rule is a bare class, so this outranks it on specificity alone and an author's real colour still wins. */
  #page-content .navbox {
    background-color: #1a1f26;
  }

  /* AUTHOR-WRITTEN INLINE COLOURS
     
     ##blue|text## emits a literal inline `color:`; the dark end of that palette is unreadable here, so lift the common names and hexes to the same hue at a legible lightness. Inline elements only, where a `background-color:` collision effectively never occurs. */

  #page-content span[style*="color:black"],
  #page-content span[style*="color: black"],
  #page-content span[style*="color:#000000"],
  #page-content span[style*="color: #000000"],
  #page-content a[style*="color:black"],
  #page-content a[style*="color: black"],
  #page-content strong[style*="color:black"],
  #page-content strong[style*="color: black"],
  #page-content em[style*="color:black"],
  #page-content em[style*="color: black"] {
    color: var(--scp-lift-black) !important;
  }

  #page-content span[style*="color:blue"],
  #page-content span[style*="color: blue"],
  #page-content span[style*="color:navy"],
  #page-content span[style*="color: navy"],
  #page-content span[style*="color:steelblue"],
  #page-content span[style*="color: steelblue"],
  #page-content span[style*="color:#0000ff"],
  #page-content span[style*="color: #0000ff"],
  #page-content span[style*="color:#00f;"],
  #page-content span[style*="color: #00f;"],
  #page-content span[style*="color:#4682b4"],
  #page-content span[style*="color: #4682b4"],
  #page-content a[style*="color:blue"],
  #page-content a[style*="color: blue"],
  #page-content a[style*="color:navy"],
  #page-content a[style*="color: navy"],
  #page-content a[style*="color:steelblue"],
  #page-content a[style*="color: steelblue"],
  #page-content strong[style*="color:blue"],
  #page-content strong[style*="color: blue"],
  #page-content strong[style*="color:steelblue"],
  #page-content strong[style*="color: steelblue"],
  #page-content em[style*="color:blue"],
  #page-content em[style*="color: blue"],
  #page-content em[style*="color:steelblue"],
  #page-content em[style*="color: steelblue"] {
    color: var(--scp-lift-blue) !important;
  }

  /* The #00f shorthand only ends a declaration when it is last in the attribute, and a loose match would swallow #00ff00. Kept in its own rule so the suffix matcher can only cost this form. */
  #page-content span[style$="color:#00f"],
  #page-content span[style$="color: #00f"] {
    color: var(--scp-lift-blue) !important;
  }

  #page-content span[style*="color:green"],
  #page-content span[style*="color: green"],
  #page-content span[style*="color:#008000"],
  #page-content span[style*="color: #008000"],
  #page-content a[style*="color:green"],
  #page-content a[style*="color: green"],
  #page-content strong[style*="color:green"],
  #page-content strong[style*="color: green"],
  #page-content em[style*="color:green"],
  #page-content em[style*="color: green"] {
    color: var(--scp-lift-green) !important;
  }

  #page-content span[style*="color:purple"],
  #page-content span[style*="color: purple"],
  #page-content span[style*="color:indigo"],
  #page-content span[style*="color: indigo"],
  #page-content span[style*="color:#800080"],
  #page-content span[style*="color: #800080"],
  #page-content span[style*="color:#880680"],
  #page-content span[style*="color: #880680"],
  #page-content a[style*="color:#880680"],
  #page-content a[style*="color: #880680"],
  #page-content a[style*="color:purple"],
  #page-content a[style*="color: purple"],
  #page-content strong[style*="color:purple"],
  #page-content strong[style*="color: purple"],
  #page-content em[style*="color:purple"],
  #page-content em[style*="color: purple"] {
    color: var(--scp-lift-purple) !important;
  }

  /* #990000 is the clearance-level red in the standard "Level n/xxxx" header snippet, so it is on a large share of articles; 2.0:1 here. */
  #page-content span[style*="color:maroon"],
  #page-content span[style*="color: maroon"],
  #page-content span[style*="color:darkred"],
  #page-content span[style*="color: darkred"],
  #page-content span[style*="color:firebrick"],
  #page-content span[style*="color: firebrick"],
  #page-content a[style*="color:firebrick"],
  #page-content a[style*="color: firebrick"],
  #page-content strong[style*="color:firebrick"],
  #page-content strong[style*="color: firebrick"],
  #page-content em[style*="color:firebrick"],
  #page-content em[style*="color: firebrick"],
  #page-content span[style*="color:#800000"],
  #page-content span[style*="color: #800000"],
  #page-content span[style*="color:#990000"],
  #page-content span[style*="color: #990000"],
  #page-content a[style*="color:maroon"],
  #page-content a[style*="color: maroon"],
  #page-content a[style*="color:#990000"],
  #page-content a[style*="color: #990000"],
  #page-content strong[style*="color:maroon"],
  #page-content strong[style*="color: maroon"],
  #page-content strong[style*="color:#990000"],
  #page-content strong[style*="color: #990000"],
  #page-content em[style*="color:maroon"],
  #page-content em[style*="color: maroon"],
  #page-content em[style*="color:#990000"],
  #page-content em[style*="color: #990000"] {
    color: var(--scp-lift-maroon) !important;
  }

  /* Pure red lands at 4.46:1, a hair under AA. Softened just enough to pass while staying the same red. */
  #page-content span[style*="color:red"],
  #page-content span[style*="color: red"],
  #page-content span[style*="color:#ff0000"],
  #page-content span[style*="color: #ff0000"],
  #page-content a[style*="color:red"],
  #page-content a[style*="color: red"],
  #page-content strong[style*="color:red"],
  #page-content strong[style*="color: red"],
  #page-content em[style*="color:red"],
  #page-content em[style*="color: red"] {
    color: var(--scp-lift-red) !important;
  }

  #page-content span[style*="color:brown"],
  #page-content span[style*="color: brown"],
  #page-content span[style*="color:sienna"],
  #page-content span[style*="color: sienna"],
  #page-content span[style*="color:#a0522d"],
  #page-content span[style*="color: #a0522d"],
  #page-content a[style*="color:brown"],
  #page-content a[style*="color: brown"],
  #page-content a[style*="color:sienna"],
  #page-content a[style*="color: sienna"],
  #page-content strong[style*="color:brown"],
  #page-content strong[style*="color: brown"],
  #page-content strong[style*="color:sienna"],
  #page-content strong[style*="color: sienna"] {
    color: var(--scp-lift-brown) !important;
  }

  /* #ce005c is the magenta half of the taboo-family palette and carries whole paragraphs, so it needs its own hue rather than the maroon lift. */
  #page-content span[style*="color:#ce005c"],
  #page-content span[style*="color: #ce005c"],
  #page-content a[style*="color:#ce005c"],
  #page-content a[style*="color: #ce005c"],
  #page-content strong[style*="color:#ce005c"],
  #page-content strong[style*="color: #ce005c"],
  #page-content em[style*="color:#ce005c"],
  #page-content em[style*="color: #ce005c"] {
    color: var(--scp-lift-pink) !important;
  }

  #page-content span[style*="color:teal"],
  #page-content span[style*="color: teal"],
  #page-content span[style*="color:#008080"],
  #page-content span[style*="color: #008080"],
  #page-content a[style*="color:teal"],
  #page-content a[style*="color: teal"],
  #page-content strong[style*="color:teal"],
  #page-content strong[style*="color: teal"] {
    color: var(--scp-lift-teal) !important;
  }

  /* Redacted / blackout spans keep working on dark */
  .bblock,
  .dblock {
    color: #000 !important;
    background-color: #000 !important;
  }

  .bblock:hover {
    color: #060 !important;
  }

  /* RATING WIDGET */

  /* Bedrock pads this box and fills the padding from its own near-white page plate. The value matches --rating-module-bg-color, which BH and theme:newspaper already resolve here; skins leaving the box transparent give it no padding. */
  .page-rate-widget-box {
    background-color: #1a1f26 !important;
    box-shadow: 1px 1px 4px rgba(0, 0, 0, .6);
  }

  div.page-rate-widget-box .rate-points {
    background-color: #5a2f2f !important;
    border-color: #5a2f2f !important;
    color: #f0e2e2 !important;
  }

  .page-rate-widget-box .rateup,
  .page-rate-widget-box .ratedown {
    background-color: #22282f !important;
    border-top-color: #5a2f2f !important;
    border-bottom-color: #5a2f2f !important;
  }

  /* Bedrock underlines these buttons in its own page plate. The element qualifier outranks a skin stating this same two-class chain !important from the page's own <style>, which the cascade orders after this sheet. */
  div.page-rate-widget-box .rateup a,
  div.page-rate-widget-box .ratedown a {
    color: #e8949a !important;
    border-color: #5a2f2f !important;
  }

  div.page-rate-widget-box .rateup a:hover,
  div.page-rate-widget-box .ratedown a:hover {
    background-color: #5a2f2f !important;
    color: #fff6f0 !important;
  }

  .page-rate-widget-box .cancel {
    background-color: #5a2f2f !important;
    border-color: #5a2f2f !important;
  }

  div.page-rate-widget-box .cancel a {
    color: #c99a9a !important;
    border-color: #7d4444 !important;
  }

  div.page-rate-widget-box .cancel a:hover {
    background-color: #7d4444 !important;
    color: #fff6f0 !important;
  }

  /* Bedrock hides each button's own glyph and draws it by clipping a ::before to a mask, so that pseudo's BACKGROUND is the mark and the colours above never reach it. Skins keeping the anchor text give the pseudo no content. */
  .page-rate-widget-box .rateup a::before,
  .page-rate-widget-box .ratedown a::before {
    background-color: #e8949a !important;
  }

  .page-rate-widget-box .cancel a::before {
    background-color: #c99a9a !important;
  }

  .page-rate-widget-box .rateup a:hover::before,
  .page-rate-widget-box .ratedown a:hover::before,
  .page-rate-widget-box .cancel a:hover::before {
    background-color: #fff6f0 !important;
  }

  /* The credit module wraps the widget in a second maroon strip; it has to track .rate-points, which is darker than the maroon the site ships. */
  .rate-box-with-credit-button {
    background-color: #5a2f2f !important;
    border-color: #5a2f2f !important;
  }

  /* The site paints this white precisely because it sits on the maroon; the page link colour drops it to ~3:1 there. */
  .creditButton a {
    color: #f0e2e2 !important;

    /* only the left side is drawn - it is the widget's separator, and pinning it stops the other three inheriting the new text colour */
    border-color: #996666 !important;
  }

  .creditButton a:hover {
    color: #fff !important;
  }

  /* The panel's surface is a background-IMAGE - a grey title strip over a white body - so a background-color alone never reaches it. */
  #u-credit-view .modalbox {
    background-color: #1c2128 !important;
    background-image: linear-gradient(#22282f 51px, #1c2128 51px, #1c2128) !important;
    border-color: #3a4048 !important;
    color: #c4cdd6 !important;
  }

  #u-credit-view .fader {
    background-color: rgba(0, 0, 0, .7) !important;
  }

  /* YUI TABS */

  .yui-navset .yui-content,
  .yui-navset .yui-navset-top .yui-content {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    border-top-color: #7d3030 !important;
    color: #c4cdd6;
  }

  .yui-navset-left .yui-content {
    border-color: #2d333b !important;
    border-left-color: #7d3030 !important;
  }

  .yui-navset-bottom .yui-content,
  .yui-navset .yui-navset-bottom .yui-content {
    border-color: #2d333b !important;
    border-bottom-color: #7d3030 !important;
  }

  .yui-navset .yui-nav,
  .yui-navset .yui-navset-top .yui-nav {
    background-color: #22282f !important;
    border-color: #7d3030 !important;
  }

  /* Bedrock holds the anchor's own fill transparent and paints the list item instead, so the anchor rule below reaches nothing there. The item takes the same pair, elsewhere showing only in the gaps. */
  .yui-navset .yui-nav li,
  .yui-navset .yui-navset-top .yui-nav li {
    background-color: #22282f !important;
  }

  .yui-navset .yui-nav li.selected,
  .yui-navset .yui-navset-top .yui-nav li.selected {
    background-color: #8a2f2f !important;
  }

  .yui-navset .yui-nav a,
  .yui-navset .yui-navset-top .yui-nav a {
    background-color: #22282f !important;
    background-image: none !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Hub pages put the label in this <em>, whose white halo on all four sides prints hollow outlined letters on a dark strip. It follows the anchor instead, so the selected tab's knocked-out white comes with it. */
