  /* HUB / INDEX CARDS
     
     The tales, series, canon, artwork and contest indexes share one card component set, every card a white plate. Only the plate and its hairlines are stated: the cards hold nothing but text and links the article rules already colour. */

  #page-content .tale-block,
  #page-content .series-block,
  #page-content .canon-block,
  #page-content .item-list .item {
    background-color: #1c2128;
    box-shadow: 0 0 .325rem rgba(0, 0, 0, .6);
  }

  /* The card's white plate is the logo's paper - the logos are transparent PNGs in black linework - so it moves onto the image once the card is dark. Only for cards still carrying the fill above: a card naming an inline background keeps the author's paper, which the logo is drawn to sit on. Matched on the VALUE, the classes being page-local. */
  #page-content .canon-block:not([style*="background"]) img,
  #page-content .series-block:not([style*="background"]) img {
    background-color: #dcdcdc;
  }

  /* The blurb / metadata separator is a 10%-black hairline, invisible once the card is dark. */
  #page-content .series-block .metadata {
    border-top-color: rgba(255, 255, 255, .12);
  }

  /* These hubs paint each card's links from --link-color, set inline per card next to the paper it was picked for; the two-id article-link rule outranks the hub's own `.canon-block a`, so the token is handed back - but only on a card that also names its own paper, a card on our fill keeping the article ink. `##` paper never paints and is excluded as everywhere else. Hover and visited take the same value: the hub draws no swap, and the article rules would otherwise turn an author's link crimson on hover. */
  #main-content #page-content .canon-block[style*="--link-color"][style*="background"]:not([style*="##"]) a,
  #main-content #page-content .canon-block[style*="--link-color"][style*="background"]:not([style*="##"]) a:visited,
  #main-content #page-content .canon-block[style*="--link-color"][style*="background"]:not([style*="##"]) a:hover,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) .blurb a,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) .blurb a:visited,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) .blurb a:hover,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) h3 a,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) h3 a:visited,
  #main-content #page-content .series-block[style*="--link-color"][style*="background"]:not([style*="##"]) h3 a:hover {
    color: var(--link-color);
  }

  /* A tale card's preview is ruled off from its tag row in #ddd. */
  #page-content .tale-block .preview {
    border-color: #3a4048;
  }

  /* The curated-series grids make each card's link inherit the card's ink. The two-id article-link rule outranks the hub's, so the inherit is restated at that weight, hover and visited included - the hub draws no swap. */
  #main-content #page-content .multi-grid > div a,
  #main-content #page-content .multi-grid > div a:visited,
  #main-content #page-content .multi-grid > div a:hover,
  #main-content #page-content .multi-grid-small > div a,
  #main-content #page-content .multi-grid-small > div a:visited,
  #main-content #page-content .multi-grid-small > div a:hover {
