  }

  /* An amber note block — kept amber, pitched for a dark panel */
  .ncmp__illustrations {
    background-color: #2a2313 !important;
    border-color: #6d5a2a !important;
    color: #e0c07a !important;
  }

  /* The consent switches encode state by track colour — filled on, grey off. */
  .ncmp__toggle label,
  .ncmp__toggle-purpose label {
    background-color: #4a5058 !important;
  }

  .ncmp__toggle input:checked + label,
  .ncmp__toggle-purpose input:checked + label {
    background-color: #8a2f2f !important;
  }

  .ncmp__toggle label::before,
  .ncmp__toggle-purpose label::before {
    background-color: #e6edf3 !important;
  }

  .ncmp__language-picker,
  .ncmp__language-picker span,
  .ncmp__language-list,
  .ncmp__banner a,
  .ncmp__modal a {
    color: #e8626e !important;
  }

  .ncmp__language-list {
    background-color: #22282f !important;
    border-color: #3a4048 !important;
  }

  /* The rail keeps its own fill, pitched down for a dark panel. After the link rule above so its items stay legible on the rail. */
  .ncmp__nav {
    background-color: #3d2020 !important;
  }

  .ncmp__nav-top {
    background-color: #4a2828 !important;
  }

  .ncmp__nav-header {
    background-color: #2e1818 !important;
    border-color: #6d3436 !important;
    color: #f0e2e2 !important;
  }

  .ncmp__nav-item,
  .ncmp__nav a,
  .ncmp__nav em {
    color: #f0e2e2 !important;
    border-color: #6d3436 !important;
  }

  /* The vendor paints this one !important from a five-class chain; the doubled class is what out-specifies it. */
  #ncmp__modal .ncmp__modal .ncmp__modal-content .ncmp__nav ul li.ncmp__nav-item.ncmp__nav-item-active.ncmp__nav-item-active a {
    background-color: #8a2f2f !important;
    color: #fff !important;
  }

  /* FOOTER / LICENSE / NAVI */

  #footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #262c33;
  }

  #footer a {
    color: #c4cdd6 !important;
  }

  #footer a:hover {
    color: #ff8f97 !important;
  }

  /* Article themes repaint this strip from their own palette and pitch its ink near-white, so a muted grey alone measures 2.0:1 there. The paper is stated with the ink so the pair is always known. */
  #license-area,
  .license-area {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  /* The licence link is the site's crimson; the themes that repaint this strip pitch their own accent at it for a light band. */
  #license-area a,
  .license-area a {
    color: var(--scp-link) !important;
  }

  #license-area a:hover,
  .license-area a:hover {
    color: var(--scp-link-hover) !important;
  }

  #navi-bar {
    background-color: #0d1117 !important;
    border-bottom-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  #navi-bar a,
  #navi-bar .action-buttons,
  #navi-bar .action-buttons a,
  #navi-bar .join,
  #navi-bar .random-site {
    color: #8ab4d8 !important;
  }

  #navi-bar .new-site input.empty {
    color: #8b949e !important;
  }

  #footer-bar {
    border-top-color: #262c33 !important;
  }

  /* Ad slots: keep them from punching a white hole in the page */
  #house-ad-1 {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  #house-ad-1 .close {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  .self-ads {
    border-color: #2d333b !important;
  }

  /* HOME PAGE - the site's own custom front-page theme */

  /* --box-accent is deliberately NOT restated: the front page's #823f3f already reads on dark, and the hubs sharing this component set declare their own code on :root and pull it through #page-content with `--box-accent: inherit`, so a value here would paint every hub the front page's maroon. */
  #page-content {
    --dark: #e6edf3;
    --light: #1c2128;
    --active: #a03636;
    /* The pair meets on the feature boxes' pill links: the ink sits on the tint, which has to stay this faint for it to clear AA. */
    --link-color: #ea6b76;
    --link-bg: #ea6b7614;
    --attention: #2a2418;
  }

  #page-content .c-scp {
    --link-color: #d98a8a;
    --link-bg: #d98a8a1f;
  }

  #page-content .c-tale {
    --link-color: #7fa3dc;
    --link-bg: #7fa3dc1f;
  }

  #page-content .c-goi {
    --link-color: #d8ac52;
    --link-bg: #d8ac521f;
  }

  #page-content .c-art {
    --link-color: #6fbc8a;
    --link-bg: #6fbc8a1f;
  }

  /* Text that must stay light because it sits on an accent/photo fill */
  #page-content .box .title,
  #page-content .caption,
  #page-content .box .title p {
    color: #f2f2f2 !important;
  }

  /* Slide-in quote panel: natively dark-on-light, kept dark-on-dark */
  #page-content .bq {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
  }

  #page-content .dropdown > a::after {
    background-color: #3a4048 !important;
    color: #e6edf3 !important;
  }

  #page-content .box,
  #page-content .dropdown-content,
  #page-content .art-slide {
    background-color: #1c2128 !important;
  }

  #page-content .feature1box:hover,
  #page-content .feature2box:hover,
  #page-content .feature3box:hover,
  #page-content .feature4box:hover,
  #page-content .feature1box:focus-within,
  #page-content .feature2box:focus-within,
  #page-content .feature3box:focus-within,
  #page-content .feature4box:focus-within {
    color: #e6edf3 !important;
  }

  /* The hover sweep is a ::before that inverts what is behind it, flashing a dark card near-white; it becomes a crimson wash instead and the ::after's screen blend is emptied. The width animation is untouched. */
  #page-content .feature1box::before,
  #page-content .feature2box::before,
  #page-content .feature3box::before,
  #page-content .feature4box::before {
    backdrop-filter: none !important;
    background-color: rgba(224, 95, 107, .13) !important;
  }

  #page-content .feature1box::after,
  #page-content .feature2box::after,
  #page-content .feature3box::after,
  #page-content .feature4box::after {
    background-color: transparent !important;
  }

  #page-content .site-news {
    --ink: #dfe3f0;
    --paper: #1a1f26;

    background-color: #171b28 !important;
    color: #dfe3f0 !important;
  }

  /* Hairlines drawn in the body ink; at full ink they glare on a dark page. */
  #page-content .low-weight h2 > span,
  #page-content .section-head h2::after,
  #page-content .low-weight h2::after {
    border-color: #8b949e !important;
  }

  #page-content .site-news .news-snippet {
    border-color: #737ea6 !important;
  }

  #page-content .site-news .news-snippet::before,
  #page-content .site-news .news-snippet::after {
    background-color: #737ea6 !important;
  }

  #page-content .placard::before,
  #page-content .placard::after {
    background: radial-gradient(at 50% 0, rgba(0, 0, 0, .45), rgba(0, 0, 0, 0) 65%) !important;
  }

  /* The event banner is author-drawn art carrying its own near-black ink, so it opts back out of the page ink and the --dark/--light remap above. */
  #page-content .event-banner {
    --dark: #333;
    --light: #fff;
    --box-accent: #823f3f;
    --active: #700;
    --link-color: #b01;
    --link-bg: #c0696014;
  }

  #page-content .event-banner,
  #page-content .event-banner p,
  #page-content .event-banner li,
  #page-content .event-banner dd,
  #page-content .event-banner dt,
  #page-content .event-banner td {
    color: #1b1815 !important;
  }

  /* The front page resets these to bare strips inside its category cards. */
  #page-content .core-categories > div > blockquote {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  /* The two inner rings are inset shadows and the outer one is the paper colour, the gap setting the blue ring off from the black frame, so it follows the card. The blue ring is the brand and the widths are the site's. */
  #page-content .INT-box {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
    box-shadow: inset 0 0 0 .175rem #1a1f26, inset 0 0 0 .675rem #4b92db !important;
  }

  #page-content .INT-box > .collapsible-block .collapsible-block-link {
    background-color: #1a1f26 !important;
    color: #6fa8e0 !important;
  }

  #page-content .INT-box > .collapsible-block .collapsible-block-content {
    border-color: #3a648c !important;
  }

  #page-content .library {
    border-color: rgba(0, 0, 0, .65) !important;
  }

  /* NEWSPAPER THEME - the Site News family */

  /* One token paints every panel this theme owns. Its two knocked-out-text uses - the selected tab's label and the unfolded collapsible's link - sit on the theme's accent and are already pinned light above. */
  :root {
    --primaryBackgroundColor: #1a1f26;
  }

  /* The panels it fills with a literal cream instead of that token. */
  #page-content .f-con,
  #page-content .tocbox .toc-u {
    background-color: #1a1f26 !important;
  }

  /* It fills a collapsible's open state with its accent and knocks the label out of it, which the article-link colour takes back - crimson on red. Clearing the fill leaves the accent ring the theme draws on the same element, so the cue survives; no other skin fills this element. */
  #page-content .collapsible-block-unfolded-link {
    background-color: transparent !important;
  }

  /* Reached from a class chain the site-wide link rule cannot outweigh, at an accent red pitched for a cream rail. */
  #side-bar div.menu-item a,
  #interwiki div.menu-item a {
    color: var(--scp-link) !important;
  }

  #side-bar div.menu-item a:hover,
  #interwiki div.menu-item a:hover {
    color: var(--scp-link-hover) !important;
  }

  /* SITE SEARCH (the Crom widget's host page) */

  #u-framewrapper {
    background-color: #14181d !important;
  }

  /* Shimmer placeholder shown until the search widget loads */
  #u-loading {
    background-image: linear-gradient(#14181d 10%, #1c2128 50%, #14181d 90%) !important;
  }

  .cromplug,
  .cromwalk,
  .cromplug p,
  .cromwalk p {
    background-color: #241b1e !important;
    border-color: #8a5f68 !important;
    color: #d8929c !important;
  }

  .cromplug p,
  .cromwalk p {
    background-color: transparent !important;
  }

  /* Crom's crow is a black silhouette drawn for the light pink box; on dark it is an invisible smudge, so drop it and keep the labelled link. */
  .cromplug {
    background-image: none !important;
  }

  .cromplug a,
  .cromwalk a {
    color: #e8626e !important;
  }

  /* INTERWIKI FRAME (other-languages box) */

  #interwiki body,
  body#interwiki {
    background-color: transparent !important;
  }

  /* The frame ELEMENT's own fill, set from the article themes' resources-block green. The frame's document normally paints over it, so it shows only while that loads - or for good, when a blocker stops the frame. */
  iframe.scpnet-interwiki-frame {
    background-color: #14181d !important;
  }

  #interwiki .menu-item a {
    color: #e8626e !important;
  }
}

@-moz-document url-prefix("https://crom.avn.sh/embed/") {
:root {
    color-scheme: dark;

    /* The widget is Tailwind - remapping its palette tokens reaches every utility at once and beats the utility layer's cascade. */
    --color-white: #171c22;
    --color-black: #0d1117;
    --color-gray-100: #262c33;
    --color-gray-200: #2d333b;
    --color-gray-300: #3a4048;
    --color-gray-400: #6b737c;
    --color-gray-500: #8b949e;
    --color-gray-600: #c4cdd6;
    --color-gray-700: #d0d8e0;
    --color-gray-800: #e0e7ee;
    --color-gray-900: #e6edf3;

    /* Crom's rose accent scale, re-pitched for a dark surface */
    --color-blush-50: #241b1e;
    --color-blush-100: #2b2124;
    --color-blush-200: #8a5f68;
    --color-blush-300: #a8737d;
    --color-blush-400: #c48792;
    --color-blush-500: #d8929c;
    --color-blush-600: #e2757f;
    --color-blush-700: #e8626e;
    --color-blush-800: #ef7d87;
    --color-blush-900: #f5a0a8;
  }

  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1;
  }
}
